package dev.aurora.minecraft.builder;

import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.state.BlockState;

/** Only source cells consume buckets. Flowing cells are generated by the normal fluid simulation. */
public final class SchematicFluids {
    private SchematicFluids() { }
    public static boolean liquid(BlockState state) {return state.is(Blocks.WATER) || state.is(Blocks.LAVA);}
    public static boolean source(BlockState state) {return liquid(state) && state.getValue(LiquidBlock.LEVEL)==0;}
    public static String item(BlockState state) {return !source(state)?"":state.is(Blocks.WATER)?"minecraft:water_bucket":"minecraft:lava_bucket";}
}
